using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class NonfieldSquareZeroActionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Minimal actual cyclic projectivity and a square-zero augmentation layer do not force a field-translation representation.",
        H("A Minimal Action Beyond Field Translations"),
        Blocks(Describe.Lean(
            DescribeId.Create("nonfield-square-zero-action"),
            DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/NonfieldSquareZeroAction.field_translation_universality_fails"),
            H("A closed refutation over the field with four elements"),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("Let K be GaloisField 2 2, the splitting field of X to the fourth minus X over ZMod 2. This is an actual field of characteristic two with four elements and prime-field degree two. Put E=Multiplicative(Fin 4 to ZMod 2), U=K times K and V=U times U. The proposition field_translation_universality quantifies over every K-linear representation tau of this fixed E on this fixed V. Its hypotheses require projectivity over K[H] for every actual cyclic subgroup H, equality with the exact lower dimension bound two times the ceiling of four divided by the prime-field degree, and vanishing of every product (tau(g)-I)(tau(h)-I). It asserts the existence of a field L with a K-algebra structure, a K-linear equivalence T from V to L times L, and a parameter function c from E to L, intertwining tau with (x,y) maps to (x+c(g)y,y). The theorem is literally the negation of this closed proposition.")),
                Paragraph(Text("Choose w in K distinct from zero and one. Such an element exists because K has four elements. Every nonzero element of K has cube one, so factoring w cubed minus one and canceling w minus one gives w squared plus w plus one equals zero, or w squared equals w plus one in characteristic two. No root or finite-field cardinality is assumed.")),
                Paragraph(Text("For t=(t0,t1,t2,t3) over ZMod 2, map each coefficient canonically into K and define A(t) by its rows: (t0+t1+w*t2, w*t1+w*t2+(1+w)*t3) and (w*t1+(1+w)*t2+t3, t0+w*t1). The four basis directions are B0=I, B1 with rows (1,w),(w,w), B2 with rows (w,w),(1+w,0), and B3 with rows (0,1+w),(1,0). The map A is additive. For all fifteen nonzero t, its determinant is nonzero, as follows by the sixteen binary coefficient cases and the relation w squared equals w plus one. An explicit adjugate divided by the determinant provides the inverse of A(t).")),
                Paragraph(Text("Define rho(g)(u,v)=(u+A(g)v,v), using the actual additive coordinates of g in E. Additivity of A proves the representation laws. Each augmentation rho(g)-I sends (u,v) to (A(g)v,0), so every product of two augmentations is zero. The group action itself commutes, and its augmentation algebra has zero multiplication. The obstruction below concerns the normalized maps on the common layer; it does not assert noncommutativity of the group action algebra.")),
                Paragraph(Text("For an arbitrary actual cyclic subgroup H, choose a generator h. Every element of E has square one. If h=1, H is trivial and the subgroup norm is the identity. Otherwise h has order two, and the bijection i maps to h to the power i from Fin 2 onto H rewrites the actual subgroup sum as I+rho(h). This norm sends (u,v) to (A(h)v,0). Invertibility of A(h) shows that a fixed vector has lower coordinate zero and supplies its norm preimage (0,A(h) inverse u). The theorem projective_iff_projective_invariants_and_norm_surjective applies to this actual restriction rho composed with H.subtype; its invariant space is projective over the field K. Thus every actual cyclic restriction is projective, including the trivial subgroup.")),
                Paragraph(Text("The space V has K-dimension four. The theorem prime_mul_ceilDiv_finrank_le_finrank_of_cyclic_projective applies to rho with p=2 and rank four. Since the prime-field degree of K is two, its lower bound is two times the ceiling of four divided by two, namely four. The constructed representation attains this exact bound. This is minimality among nonzero finite-dimensional representations of the same E over K whose actual cyclic restrictions are all projective.")),
                Paragraph(Text("Suppose T intertwines rho with scalar shears over an arbitrary K-algebra field L. In the identity code direction g0, the augmentation sends (u,v) to (v,0). Its parameter c0 must be nonzero: otherwise injectivity of T would kill this nonzero augmentation. Applying the intertwining identity to (u,0) shows that T(u,0) has second coordinate zero. Write P(u) for its first coordinate and R(u) for the second coordinate of T(0,u). Injectivity of T implies injectivity of P, and the identity direction gives P(u)=c0*R(u).")),
                Paragraph(Text("For a general direction g, the same identity gives P(A(g)u)=c(g)*R(u). Normalizing by c0 therefore makes P intertwine every A(g) with multiplication by c(g)/c0 in L. Multiplication in a field is commutative; applying the formula twice and using injectivity of P forces A(g)A(h)u=A(h)A(g)u for every g,h,u. This consequence is derived from the arbitrary equivalence T itself, so it is invariant under changes of basis of the full representation space.")),
                Paragraph(Text("For the displayed B1 and B2, the second coordinate of B1*B2 applied to (1,0) is w, whereas that of B2*B1 applied to (1,0) is 1+w. Equality would force one to be zero. This contradiction excludes every field L and every parameter function c. In particular it excludes every degree-two extension and every group relabeling, since relabeling can be absorbed into c.")),
                Paragraph(Text("The result distinguishes field-scalar shears from other minimal square-zero actions without classifying all such actions, their commutants or their endomorphism rings. It is a directly constructed finite counterexample and makes no literature novelty or uniqueness claim."))),
            DescribeRole.Theorem))));
}
